async function envoyerNom(nom) {
  const entetes = new Headers({"Content-Type":"application/json"});
  const requete = new Request("/api-pedagogique/v1/inscriptions", {method:"POST", headers:entetes, body:JSON.stringify({atelierId:1, nom:nom})});
  const r = await fetch(requete);
  const corps = await r.json();
  return corps.nom;
}

