starter_code:
async function accuse(atelierId, nom) {
  return {statut:200, provenance:"", nom:nom};
}

solution:
async function accuse(atelierId, nom) {
  const r = await fetch("/api-pedagogique/v1/inscriptions", {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({atelierId:atelierId, nom:nom})});
  const donnees = await r.json();
  return {statut:r.status, provenance:r.headers.get("X-Nunya-Api"), nom:donnees.nom};
}

